"""
Pre-flight compatibility checks for environment installation.

Provides a single entry point — ``check_env_install_preflight`` — that inspects
an environment's metadata against the current system and returns a structured
result.  Callers (CLI interactive, CLI ``--yes``, lab SSE handler, projects
install) can then decide how to proceed based on the result without duplicating
the validation logic.
"""

from __future__ import annotations

import logging
from dataclasses import dataclass
from typing import Optional

logger = logging.getLogger(__name__)


@dataclass
class EnvInstallPreflight:
    """Result of pre-flight compatibility checks for environment installation.

    Attributes:
        platform_compatible: True if the env platform matches or is close enough.
        platform_warning: Human-readable warning when platform mismatches.
        env_platform: Platform string from the environment metadata.
        current_platform: Detected platform of the running system.
        python_available: True if the required Python version is found locally.
        required_python: ``major.minor`` string (e.g. ``"3.11"``) or None.
        python_warning: Human-readable warning when Python is missing.
        uv_available: Whether ``uv`` is on PATH (can auto-install Python).
    """

    # Platform
    platform_compatible: bool = True
    platform_warning: Optional[str] = None
    env_platform: Optional[str] = None
    current_platform: str = ""

    # Python
    python_available: bool = True
    required_python: Optional[str] = None
    python_warning: Optional[str] = None
    uv_available: bool = False

    @property
    def can_download_directly(self) -> bool:
        """True when no compatibility issues were found."""
        return self.platform_compatible and self.python_available

    @property
    def issues(self) -> list[str]:
        """Collect all warnings into a list (empty when everything is fine)."""
        msgs: list[str] = []
        if self.platform_warning:
            msgs.append(self.platform_warning)
        if self.python_warning:
            msgs.append(self.python_warning)
        return msgs


def check_env_install_preflight(env_info: dict) -> EnvInstallPreflight:
    """Run platform and Python compatibility checks for an environment.

    Args:
        env_info: Environment metadata dict as returned by the qBraid API.
            Expected keys: ``platform`` (str), ``pythonVersion`` (str).

    Returns:
        An ``EnvInstallPreflight`` describing what (if anything) is incompatible.
    """
    from .python import find_python, is_uv_available
    from .registry import get_current_platform
    from .validate import PlatformCompatibility, validate_platform_compatibility

    result = EnvInstallPreflight()

    # ── Platform ──────────────────────────────────────────────────────────
    env_platform = env_info.get("platform")
    current_platform = get_current_platform()
    result.env_platform = env_platform
    result.current_platform = current_platform

    if env_platform:
        platform_result = validate_platform_compatibility(env_platform, current_platform)
        if platform_result.compatibility in (
            PlatformCompatibility.INCOMPATIBLE,
            PlatformCompatibility.EMULATION_WARNING,
        ):
            result.platform_compatible = False
            result.platform_warning = (
                f"Environment was built for {env_platform}, "
                f"but current platform is {current_platform}"
            )

    # ── Python version ────────────────────────────────────────────────────
    env_python = env_info.get("pythonVersion")
    if env_python:
        parts = env_python.split(".")
        required = f"{parts[0]}.{parts[1]}" if len(parts) >= 2 else env_python
        result.required_python = required

        python_info = find_python(required)
        if python_info is None:
            result.python_available = False
            result.python_warning = f"Python {required} is not available on this system"

    result.uv_available = is_uv_available()

    return result
